import javax.naming.Context
import javax.naming.directory.*
import javax.naming.ldap.LdapName
import javax.naming.ldap.Rdn
import java.util.Hashtable

data class LdapConfig(
    val host: String = System.getenv("LDAP_HOST") ?: "ldaps://ldap.internal:636",
    val bindDn: String = System.getenv("LDAP_BIND_DN") ?: "cn=svc-reader,ou=services,dc=corp,dc=internal",
    val bindPassword: String = System.getenv("LDAP_BIND_PASSWORD") ?: "",
    val baseDn: String = System.getenv("LDAP_BASE_DN") ?: "ou=users,dc=corp,dc=internal",
    val maxSearchDepth: Int = (System.getenv("LDAP_MAX_DEPTH") ?: "3").toInt()
)

object RfcEncoder {
    // Full RFC 4515 filter value encoding
    fun encodeFilterValue(input: String): String {
        val sb = StringBuilder()
        for (ch in input) {
            when (ch) {
                '\\' -> sb.append("\\5c")
                '*' -> sb.append("\\2a")
                '(' -> sb.append("\\28")
                ')' -> sb.append("\\29")
                '\u0000' -> sb.append("\\00")
                else -> sb.append(ch)
            }
        }
        return sb.toString()
    }

    // RFC 4514 DN component encoding
    fun encodeDnValue(input: String): String {
        val sb = StringBuilder()
        for ((i, ch) in input.withIndex()) {
            when {
                ch == ',' -> sb.append("\\,")
                ch == '+' -> sb.append("\\+")
                ch == '"' -> sb.append("\\\"")
                ch == '\\' -> sb.append("\\\\")
                ch == '<' -> sb.append("\\<")
                ch == '>' -> sb.append("\\>")
                ch == ';' -> sb.append("\\;")
                ch == '=' && i == 0 -> sb.append("\\=")
                ch == ' ' && (i == 0 || i == input.length - 1) -> sb.append("\\ ")
                ch == '#' && i == 0 -> sb.append("\\#")
                else -> sb.append(ch)
            }
        }
        return sb.toString()
    }
}

class DirectorySearchService(private val config: LdapConfig = LdapConfig()) {

    private fun createContext(): InitialDirContext {
        val env = Hashtable<String, String>()
        env[Context.INITIAL_CONTEXT_FACTORY] = "com.sun.jndi.ldap.LdapCtxFactory"
        env[Context.PROVIDER_URL] = config.host
        env[Context.SECURITY_AUTHENTICATION] = "simple"
        env[Context.SECURITY_PRINCIPAL] = config.bindDn
        env[Context.SECURITY_CREDENTIALS] = config.bindPassword
        if (config.host.startsWith("ldaps://")) {
            env[Context.SECURITY_PROTOCOL] = "ssl"
        } else {
            throw SecurityException("Non-TLS LDAP connections are not permitted")
        }
        return InitialDirContext(env)
    }

    /**
     * Computes the relative depth of a target DN beneath the configured base DN.
     * Returns the number of additional RDN components the target has beyond the base.
     * Used to enforce search scope restrictions.
     */
    private fun computeRelativeDepth(targetDn: String, baseDn: String): Int {
        // Normalize by removing spaces around commas for consistent comparison
        val normalizedTarget = targetDn.replace("\\s*,\\s*".toRegex(), ",").lowercase()
        val normalizedBase = baseDn.replace("\\s*,\\s*".toRegex(), ",").lowercase()

        if (!normalizedTarget.endsWith(normalizedBase)) {
            return -1 // Target is not under base DN
        }

        // Calculate depth by counting comma-separated components difference
        val targetComponents = normalizedTarget.split(",").size
        val baseComponents = normalizedBase.split(",").size
        return targetComponents - baseComponents
    }

    /**
     * Validates that the requested search DN is within allowed depth from base.
     * This prevents searches from traversing too far up or across the directory tree.
     */
    private fun validateSearchScope(requestedOu: String): String {
        // Build the full target DN from the requested OU
        val targetDn = if (requestedOu.isBlank()) {
            config.baseDn
        } else {
            // Encode the OU value to prevent DN injection
            val encodedOu = RfcEncoder.encodeDnValue(requestedOu)
            "ou=${encodedOu},${config.baseDn}"
        }

        val depth = computeRelativeDepth(targetDn, config.baseDn)

        // Depth must be non-negative (under base) and within max
        if (depth < 0 || depth > config.maxSearchDepth) {
            throw SecurityException("Search scope violation: depth $depth exceeds maximum ${config.maxSearchDepth}")
        }

        return targetDn
    }

    /**
     * Search for users matching a filter within a specified organizational unit.
     * Both the OU path and the search term are properly encoded.
     */
    fun searchUsers(organizationalUnit: String, searchTerm: String): List<Map<String, String>> {
        val ctx = createContext()
        try {
            val searchDn = validateSearchScope(organizationalUnit)
            val encodedTerm = RfcEncoder.encodeFilterValue(searchTerm)
            val filter = "(&(objectClass=inetOrgPerson)(|(cn=${encodedTerm})(uid=${encodedTerm})))"

            val controls = SearchControls()
            controls.searchScope = SearchControls.SUBTREE_SCOPE
            controls.returningAttributes = arrayOf("cn", "uid", "mail", "memberOf")
            controls.countLimit = 100

            val results = ctx.search(searchDn, filter, controls)
            val entries = mutableListOf<Map<String, String>>()

            while (results.hasMore()) {
                val entry = results.next()
                val attrs = entry.attributes
                val map = mutableMapOf<String, String>()
                map["dn"] = entry.nameInNamespace
                map["cn"] = attrs.get("cn")?.get()?.toString() ?: ""
                map["uid"] = attrs.get("uid")?.get()?.toString() ?: ""
                map["mail"] = attrs.get("mail")?.get()?.toString() ?: ""
                map["memberOf"] = attrs.get("memberOf")?.get()?.toString() ?: ""
                entries.add(map)
            }
            return entries
        } finally {
            ctx.close()
        }
    }

    /**
     * Resolve a user's group memberships by searching from a custom base.
     * The caller specifies which subtree to search within.
     */
    fun resolveGroupMemberships(userId: String, searchBase: String?): List<String> {
        val ctx = createContext()
        try {
            // If searchBase is provided, use it directly after validation
            val effectiveBase = if (searchBase != null && searchBase.isNotBlank()) {
                validateDirectDn(searchBase)
            } else {
                config.baseDn
            }

            val encodedUid = RfcEncoder.encodeFilterValue(userId)
            val filter = "(&(objectClass=groupOfNames)(member=uid=${encodedUid},${config.baseDn}))"

            val controls = SearchControls()
            controls.searchScope = SearchControls.SUBTREE_SCOPE
            controls.returningAttributes = arrayOf("cn")

            val results = ctx.search(effectiveBase, filter, controls)
            val groups = mutableListOf<String>()
            while (results.hasMore()) {
                val entry = results.next()
                groups.add(entry.attributes.get("cn")?.get()?.toString() ?: "")
            }
            return groups
        } finally {
            ctx.close()
        }
    }

    /**
     * Validates a directly-provided DN to ensure it's under the configured base.
     * Uses string suffix matching after normalization.
     */
    private fun validateDirectDn(dn: String): String {
        val normalizedDn = dn.replace("\\s*,\\s*".toRegex(), ",").trim()
        val normalizedBase = config.baseDn.replace("\\s*,\\s*".toRegex(), ",").trim()

        // Ensure the provided DN ends with our base DN (case-insensitive)
        if (!normalizedDn.lowercase().endsWith(normalizedBase.lowercase())) {
            throw SecurityException("DN '$dn' is not within the allowed base '${config.baseDn}'")
        }

        // Verify depth constraint
        val depth = computeRelativeDepth(normalizedDn, normalizedBase)
        if (depth < 0 || depth > config.maxSearchDepth) {
            throw SecurityException("DN depth $depth exceeds maximum ${config.maxSearchDepth}")
        }

        return normalizedDn
    }
}

// HTTP handler for the search API
class SearchController(private val service: DirectorySearchService = DirectorySearchService()) {

    fun handleSearchRequest(params: Map<String, String>): Map<String, Any> {
        val ou = params["ou"] ?: ""
        val query = params["q"] ?: return mapOf("error" to "Missing search query")

        return try {
            val results = service.searchUsers(ou, query)
            mapOf("results" to results, "count" to results.size)
        } catch (e: SecurityException) {
            mapOf("error" to e.message.orEmpty())
        }
    }

    fun handleGroupLookup(params: Map<String, String>): Map<String, Any> {
        val userId = params["uid"] ?: return mapOf("error" to "Missing user ID")
        val base = params["base"]

        return try {
            val groups = service.resolveGroupMemberships(userId, base)
            mapOf("groups" to groups, "count" to groups.size)
        } catch (e: SecurityException) {
            mapOf("error" to e.message.orEmpty())
        }
    }
}
